namespace coincide::background_host_idle_fixture {
struct State {bool active{},paused{true};std::vector<AgentQueuedTurn> pending;std::vector<SessionEvent> events;std::uint64_t takes{},snapshots{};};
class Session final:public AgentSession {
    std::shared_ptr<State> state_;
public:
    explicit Session(std::shared_ptr<State> state):state_(std::move(state)){}
    bool send(CodexTurn input)override{state_->events.push_back({SessionEvent::Kind::input,"",std::move(input.text),""});return true;}
    bool busy()const noexcept override{return state_->active||(!state_->paused&&!state_->pending.empty());}
    void interrupt()noexcept override{state_->active=false;state_->paused=true;}
    bool refresh_models()override{state_->events.push_back({SessionEvent::Kind::models,"",R"({"data":[{"id":"idle-fixture"}]})",""});return true;}
    bool queue(CodexTurn turn,std::string id)override{state_->pending.push_back({std::move(id),std::move(turn)});return true;}
    std::vector<AgentQueuedTurn> queued()const override{++state_->snapshots;return state_->pending;}
    std::size_t queued_count()const override{return state_->pending.size();}bool queue_paused()const override{return state_->paused;}
    bool remove_queued(const std::string& id)override{const auto old=state_->pending.size();std::erase_if(state_->pending,[&](const auto& value){return value.id==id;});return old!=state_->pending.size();}
    bool edit_queued(const std::string& id,CodexTurn turn)override{for(auto& value:state_->pending)if(value.id==id){value.turn=std::move(turn);return true;}return false;}
    bool resume_queue()override{state_->paused=false;return true;}bool pause_queue()override{state_->paused=true;return true;}
    bool steer(CodexTurn,std::string)override{return false;}void respond(std::string,std::string)override{}
    std::vector<SessionEvent> take_events()override{++state_->takes;auto result=std::move(state_->events);state_->events.clear();return result;}
    void close()noexcept override{}void shutdown()noexcept override{interrupt();}
};
} // namespace coincide::background_host_idle_fixture

